    /**
     * Filter the query on the RADICADO column
     *
     * Example usage:
     * <code>
     * $query->filterByRadicado('fooValue');   // WHERE RADICADO = 'fooValue'
     * $query->filterByRadicado('%fooValue%'); // WHERE RADICADO LIKE '%fooValue%'
     * </code>
     *
     * @param     string $radicado The value to use as filter.
     *              Accepts wildcards (* and % trigger a LIKE)
     * @param     string $comparison Operator to use for the column comparison, defaults to Criteria::EQUAL
     *
     * @return ComEnviadaQuery The current query, for fluid interface
     */
    public function filterByRadicado($radicado = null, $comparison = null)
    {
        if (null === $comparison) {
            if (is_array($radicado)) {
                $comparison = Criteria::IN;
            } elseif (preg_match('/[\%\*]/', $radicado)) {
                $radicado = str_replace('*', '%', $radicado);
                $comparison = Criteria::LIKE;
            }
        }

        return $this->addUsingAlias(ComEnviadaPeer::RADICADO, $radicado, $comparison);
    }

